<?php
require_once __DIR__ . '/../assets/php/layout.php';
require_admin();
$categories=['accounts'=>'Accounts & access','devices'=>'Devices','settings'=>'Settings & storage','alerts'=>'Alerts','sessions'=>'Sign-ins'];
$category=(string)($_GET['category']??'all');if($category!=='all'&&!isset($categories[$category]))$category='all';
$categoryOf=static function(string $action):string{return match(true){str_starts_with($action,'user_'),str_starts_with($action,'password_reset_')=>'accounts',str_starts_with($action,'device_')=>'devices',str_starts_with($action,'alert_')=>'alerts',in_array($action,['thresholds_updated','notification_settings_updated','retention_settings_updated','readings_retention_cleanup'],true)=>'settings',in_array($action,['login','logout'],true)=>'sessions',default=>'settings'};};
try{$allRows=db()->query('SELECT l.*,u.name FROM audit_log l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC LIMIT 200')->fetchAll();}catch(Throwable $exception){$allRows=[];}
$counts=array_fill_keys(array_keys($categories),0);foreach($allRows as $row)$counts[$categoryOf((string)$row['action'])]++;
$filteredRows=$category==='all'?$allRows:array_values(array_filter($allRows,static fn($row)=>$categoryOf((string)$row['action'])===$category));
$pageSize=10;$requestedPage=filter_var($_GET['page']??1,FILTER_VALIDATE_INT);$page=max(1,$requestedPage===false?1:$requestedPage);$pageCount=max(1,(int)ceil(count($filteredRows)/$pageSize));$page=min($page,$pageCount);$rows=array_slice($filteredRows,($page-1)*$pageSize,$pageSize);
$pageUrl=static fn(int $number):string=>app_url('pages/admin_log.php?'.http_build_query(['category'=>$category,'page'=>$number]));
layout_start('Activity log','admin_log');
?>
<section class="content-card"><div class="section-heading"><div><h2>Recent activity</h2><p>Latest 200 events, grouped by what changed</p></div><span class="status-pill neutral"><?= count($filteredRows) ?> events</span></div><nav class="segmented admin-filter-tabs" aria-label="Filter activity"><a class="<?= $category==='all'?'selected':'' ?>" href="<?= e(app_url('pages/admin_log.php?category=all')) ?>">All <?= count($allRows) ?></a><?php foreach($categories as $key=>$label): ?><a class="<?= $category===$key?'selected':'' ?>" href="<?= e(app_url('pages/admin_log.php?category='.$key)) ?>"><?= e($label) ?> <?= $counts[$key] ?></a><?php endforeach; ?></nav><?php if(!$rows): ?><p class="empty-state">No events in this category.</p><?php else: ?><div class="table-scroll"><table><thead><tr><th>Time (UTC)</th><th>User</th><th>Category</th><th>Action</th><th>Details</th></tr></thead><tbody><?php foreach($rows as $row): $rowCategory=$categoryOf((string)$row['action']); ?><tr><td><?= e($row['created_at']) ?></td><td><?= e($row['name']??'System') ?></td><td><?= e($categories[$rowCategory]) ?></td><td><?= e($row['action']) ?></td><td><?= e($row['details']) ?></td></tr><?php endforeach; ?></tbody></table></div><nav class="reading-pagination" aria-label="Activity pages"><?php if($page>1): ?><a href="<?= e($pageUrl($page-1)) ?>" rel="prev">‹ Previous</a><?php endif; ?><span>Page <?= $page ?> of <?= $pageCount ?> · latest 200 events</span><?php if($page<$pageCount): ?><a href="<?= e($pageUrl($page+1)) ?>" rel="next">Next ›</a><?php endif; ?></nav><?php endif; ?></section>
<?php layout_end(); ?>

